/* =========================================================
   DUNE & DUST — mobile archaeological adventure
   ========================================================= */
@font-face {
  font-family: 'Fraunces';
  src: url('assets/fonts/fraunces-600.woff2') format('woff2');
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Manrope';
  src: url('assets/fonts/manrope-400.woff2') format('woff2');
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

:root {
  --ink: #1d150e;
  --ink-2: #3f3021;
  --ink-3: #77634c;
  --paper: #f3e8d3;
  --paper-2: #ead9ba;
  --paper-3: #dfcba7;
  --cream: #fff8ea;
  --gold: #d8a44d;
  --gold-deep: #a66b24;
  --gold-light: #f3cf84;
  --rust: #b45a32;
  --teal: #1d5b55;
  --teal-deep: #0e3b38;
  --night: #15100b;
  --night-2: #211810;
  --line: rgba(63, 43, 23, .16);
  --line-strong: rgba(63, 43, 23, .28);
  --shadow: 0 18px 45px rgba(67, 42, 16, .18);
  --font-display: 'Fraunces', 'Iowan Old Style', 'Palatino Linotype', Georgia, serif;
  --font-body: 'Manrope', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --tab-h: 66px;
}

* { box-sizing: border-box; }
html, body { height: 100%; }
html {
  background: #0c0906;
  overflow: hidden;
  -webkit-text-size-adjust: 100%;
}
body {
  margin: 0;
  overflow: hidden;
  position: fixed;
  inset: 0;
  background:
    radial-gradient(ellipse at 50% -10%, #5e4228 0%, #1a120b 48%, #0a0705 100%);
  font-family: var(--font-body);
  color: var(--ink);
  overscroll-behavior: none;
  touch-action: none;
  -webkit-tap-highlight-color: transparent;
  -webkit-user-select: none;
  user-select: none;
}
button {
  font: inherit;
  color: inherit;
  border: 0;
  background: none;
  padding: 0;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
button:focus-visible { outline: 2px solid var(--gold); outline-offset: 3px; }
button:disabled { cursor: default; }
img { display: block; max-width: 100%; }
p, h1, h2, h3 { margin: 0; }
[hidden] { display: none !important; }

.svg-sprite { position: absolute; width: 0; height: 0; overflow: hidden; }
svg { display: block; }
.icon-btn svg, .tab svg, .wallet svg, .primary-btn svg, .scan-btn svg,
.dispatch-card svg, .tool-btn svg, .offer-card svg, .seg svg { width: 21px; height: 21px; }

.app {
  position: relative;
  width: min(100%, 520px);
  height: 100dvh;
  max-height: 100dvh;
  margin: 0 auto;
  overflow: hidden;
  background: var(--paper);
  isolation: isolate;
  box-shadow: 0 0 80px rgba(0, 0, 0, .55);
}
@media (min-width: 560px) {
  .app { border-left: 1px solid rgba(255,255,255,.06); border-right: 1px solid rgba(255,255,255,.06); }
}

.ambient-grain {
  position: fixed;
  inset: 0;
  z-index: 60;
  pointer-events: none;
  opacity: .055;
  mix-blend-mode: multiply;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 160 160' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.7'/%3E%3C/svg%3E");
  background-size: 150px 150px;
}

.screen {
  position: absolute;
  inset: 0;
  display: none;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
  background: var(--paper);
}
.screen.is-active { display: flex; animation: screenIn .46s cubic-bezier(.2,.8,.2,1) both; }
@keyframes screenIn {
  from { opacity: 0; transform: translateY(8px) scale(.996); }
  to { opacity: 1; transform: none; }
}

/* =========================================================
   Shared bits
   ========================================================= */
.eyebrow, .mini-label, .page-kicker, .stat-label, .dispatch-label,
.brand-sub, .season-line, .tag, .lab-tag, .hud-chip, .field-note,
.tool-name, .site-index, .sold-summary i, .appraise-stats i {
  font-family: var(--font-body);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .16em;
}
.eyebrow { font-size: 9px; line-height: 1.4; }
.mini-label { font-size: 8px; color: var(--ink-3); letter-spacing: .19em; }
.tag {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding: 0 9px;
  border-radius: 999px;
  font-size: 8px;
  letter-spacing: .14em;
  background: rgba(24, 16, 9, .76);
  color: #f6e7c8;
  backdrop-filter: blur(8px);
}
.tag-light { background: rgba(255, 246, 226, .18); border: 1px solid rgba(255,255,255,.24); }

.icon-btn {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: var(--ink-2);
  background: rgba(255,255,255,.38);
  border: 1px solid var(--line);
  backdrop-filter: blur(10px);
  transition: transform .15s ease, background .2s ease;
}
.icon-btn:active { transform: scale(.93); background: rgba(255,255,255,.65); }
.icon-btn svg { width: 19px; height: 19px; }

.wallet {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 38px;
  padding: 0 13px 0 10px;
  border-radius: 999px;
  background: #21170e;
  color: #f7e8c9;
  border: 1px solid rgba(216, 164, 77, .42);
  box-shadow: 0 6px 16px rgba(36, 20, 4, .18);
  font-family: var(--font-body);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: .02em;
}
.wallet svg { width: 18px; height: 18px; color: var(--gold-light); }
.wallet.is-bumping { animation: walletBump .38s ease; }
@keyframes walletBump { 0%,100% { transform: none; } 35% { transform: scale(1.08); } 65% { transform: scale(.98); } }

.primary-btn {
  height: 54px;
  border-radius: 15px;
  background: linear-gradient(180deg, #f2cb78 0%, #d9a246 52%, #c58b32 100%);
  color: #25180a;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 0 18px;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: .025em;
  box-shadow: 0 7px 0 #8f5f1f, 0 14px 24px rgba(53, 32, 9, .28), inset 0 1px 0 rgba(255,255,255,.6);
  transition: transform .12s ease, box-shadow .12s ease, filter .2s ease;
  position: relative;
  overflow: hidden;
}
.primary-btn::after {
  content: '';
  position: absolute;
  top: 0; bottom: 0;
  width: 42%;
  left: -60%;
  background: linear-gradient(100deg, transparent, rgba(255,255,255,.35), transparent);
  transform: skewX(-20deg);
  animation: btnShine 4.8s ease-in-out infinite 1.8s;
}
@keyframes btnShine { 0%, 62% { left: -60%; } 82%, 100% { left: 130%; } }
.primary-btn svg { width: 19px; height: 19px; flex: 0 0 auto; }
.primary-btn:active { transform: translateY(3px); box-shadow: 0 3px 0 #8f5f1f, 0 7px 14px rgba(53,32,9,.25), inset 0 1px 0 rgba(255,255,255,.5); }
.primary-btn:disabled {
  background: linear-gradient(180deg, #b6a58b, #8e7b62);
  color: rgba(255,248,234,.55);
  box-shadow: 0 4px 0 #625440, inset 0 1px 0 rgba(255,255,255,.22);
  filter: saturate(.5);
}
.primary-btn:disabled::after { display: none; }
.primary-btn.compact { height: 46px; border-radius: 13px; padding: 0 15px; font-size: 11.5px; box-shadow: 0 5px 0 #8f5f1f, 0 10px 18px rgba(53,32,9,.24); }
.primary-btn.compact:active { transform: translateY(2px); box-shadow: 0 2px 0 #8f5f1f; }
.primary-btn.compact svg { width: 17px; height: 17px; }

.meter {
  height: 7px;
  border-radius: 99px;
  background: rgba(69, 47, 25, .13);
  overflow: hidden;
  position: relative;
}
.meter > span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #c27c32, #e5b659);
  transition: width .22s ease;
}
.meter-salt > span { background: linear-gradient(90deg, #5e9995, #a8d6ce); }
.meter-notch { position: absolute; top: 0; bottom: 0; width: 1px; background: rgba(255,255,255,.65); }

/* =========================================================
   HOME
   ========================================================= */
.screen-home {
  background:
    radial-gradient(ellipse at 18% -12%, rgba(255, 231, 182, .9) 0%, rgba(247, 220, 173, .35) 38%, transparent 66%),
    linear-gradient(180deg, #f0e2c7 0%, #f4ead7 44%, #ebdcc1 100%);
  padding-top: var(--safe-top);
}
.screen-home::before {
  content: '';
  position: absolute;
  width: 330px;
  height: 330px;
  right: -160px;
  top: -190px;
  border-radius: 50%;
  border: 1px solid rgba(143, 98, 40, .12);
  box-shadow: 0 0 0 38px rgba(143,98,40,.03), 0 0 0 78px rgba(143,98,40,.025);
  pointer-events: none;
}
.topbar {
  flex: 0 0 auto;
  height: 66px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 16px 0;
  position: relative;
  z-index: 3;
}
.brand { display: flex; align-items: center; gap: 10px; }
.brand-seal {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: #4d351d;
  border: 1px solid rgba(83, 55, 24, .32);
  background: radial-gradient(circle at 35% 28%, #fff7e8, #e8d3ae);
  box-shadow: inset 0 0 0 3px rgba(255,255,255,.3), 0 4px 10px rgba(80, 50, 15, .1);
  position: relative;
}
.brand-seal::after { content: ''; position: absolute; inset: 4px; border: 1px dotted rgba(85, 57, 25, .35); border-radius: 50%; }
.brand-seal svg { width: 22px; height: 22px; }
.brand-copy { display: flex; flex-direction: column; gap: 1px; }
.brand-title {
  font-family: var(--font-display);
