  z-index: 3;
}
.hero-coord { font-size: 7px; letter-spacing: .19em; font-weight: 700; color: rgba(255,245,222,.65); text-transform: uppercase; }
.hero-arrow {
  position: absolute;
  top: 45%;
  z-index: 4;
  width: 32px; height: 32px;
  border-radius: 50%;
  display: grid; place-items: center;
  color: #f9eccf;
  background: rgba(24, 15, 8, .26);
  border: 1px solid rgba(255,255,255,.24);
  backdrop-filter: blur(7px);
  transition: transform .15s ease, background .2s;
}
.hero-arrow svg { width: 16px; height: 16px; }
.hero-arrow.prev { left: 10px; }
.hero-arrow.next { right: 10px; }
.hero-arrow:active { transform: scale(.9); background: rgba(24,15,8,.5); }
.hero-copy {
  position: absolute;
  left: 18px; right: 18px; bottom: 76px;
