.upgrade-buy:disabled:not(.is-max) { opacity: .55; }
.shop-note { flex: 0 0 auto; min-height: 38px; border-radius: 11px; border: 1px solid rgba(80,52,22,.1); background: rgba(255,251,241,.26); display: flex; align-items: center; gap: 7px; padding: 6px 9px; color: #91744e; font-size: 6.8px; line-height: 1.35; }
.shop-note svg { width: 13px; height: 13px; color: #b1823f; flex: 0 0 auto; }

/* =========================================================
   MODAL / TOAST
   ========================================================= */
.toast-layer {
  position: absolute;
  left: 50%;
  bottom: calc(var(--tab-h) + var(--safe-bottom) + 22px);
  z-index: 80;
  transform: translateX(-50%);
  width: min(88%, 360px);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  pointer-events: none;
}
.toast {
  width: fit-content;
  max-width: 100%;
  background: rgba(28, 19, 11, .93);
  color: #f6e6c8;
  border: 1px solid rgba(239,203,134,.2);
  border-radius: 999px;
  padding: 9px 14px;
  font-size: 9px;
  font-weight: 600;
  line-height: 1.35;
  text-align: center;
  box-shadow: 0 10px 30px rgba(0,0,0,.3);
  backdrop-filter: blur(12px);
  animation: toastIn .35s ease both;
}
.toast.is-leaving { animation: toastOut .3s ease both; }
@keyframes toastIn { from { opacity: 0; transform: translateY(8px) scale(.97); } to { opacity: 1; transform: none; } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-5px) scale(.98); } }

.modal { position: absolute; inset: 0; z-index: 90; display: grid; place-items: center; padding: 24px; }
.modal-scrim { position: absolute; inset: 0; background: rgba(15, 10, 6, .62); backdrop-filter: blur(7px); animation: fadeIn .25s ease both; }
.modal-card {
  position: relative;
  width: 100%;
  max-width: 330px;
  border-radius: 22px;
  padding: 24px 20px 18px;
  background:
    radial-gradient(ellipse at 50% -10%, #fff6e3, transparent 55%),
    linear-gradient(180deg, #f5ead5, #e9d8b9);
  border: 1px solid rgba(255,255,255,.5);
  box-shadow: 0 28px 70px rgba(0,0,0,.4);
  animation: soldIn .35s cubic-bezier(.2,.9,.2,1.05) both;
}
.modal-close { position: absolute; top: 11px; right: 11px; width: 29px; height: 29px; border-radius: 50%; display: grid; place-items: center; color: #7d6242; background: rgba(80,52,22,.06); }
.modal-close svg { width: 15px; height: 15px; }
.modal-kicker { display: block; font-size: 6.5px; font-weight: 700; letter-spacing: .2em; text-transform: uppercase; color: #a07a48; margin-bottom: 7px; }
.modal-card h2 { font-family: var(--font-display); font-size: 25px; line-height: 1.05; font-weight: 600; color: #2c1d0e; letter-spacing: -.02em; }
.modal-card p { font-size: 9.5px; line-height: 1.5; color: #826641; margin-top: 8px; }
.modal-actions { display: flex; flex-direction: column; gap: 7px; margin-top: 17px; }
.modal-actions .primary-btn { width: 100%; }
.ghost-btn { height: 44px; border-radius: 12px; border: 1px solid rgba(80,52,22,.16); color: #6f5536; font-size: 10px; font-weight: 700; letter-spacing: .03em; }
.ghost-btn:active { background: rgba(80,52,22,.06); }

/* guide modal steps */
.guide-steps { display: flex; flex-direction: column; gap: 9px; margin-top: 14px; }
.guide-step { display: flex; gap: 9px; align-items: flex-start; }
.guide-num { width: 22px; height: 22px; border-radius: 50%; display: grid; place-items: center; background: #2b1e11; color: #f2d79e; font-family: var(--font-display); font-size: 11px; flex: 0 0 auto; }
.guide-step strong { display: block; font-size: 10px; color: #3a2715; }
.guide-step span { display: block; font-size: 8px; color: #8a6b45; line-height: 1.4; margin-top: 1px; }

