.guide-step span { display: block; font-size: 8px; color: #8a6b45; line-height: 1.4; margin-top: 1px; }

/* =========================================================
   Responsive tweaks
   ========================================================= */
@media (max-height: 760px) {
  :root { --tab-h: 60px; }
  .topbar { height: 58px; }
  .brand-title { font-size: 20px; }
  .brand-seal { width: 34px; height: 34px; }
  .brand-seal svg { width: 20px; height: 20px; }
  .hero { height: 306px; min-height: 270px; }
  .hero-copy { bottom: 70px; }
  .hero-copy h1 { font-size: 30px; }
  .hero-cta { height: 47px; }
  .site-rail { height: 47px; }
  .home-lower { gap: 5px; }
  .stat-pair { height: 45px; }
  .dispatch-card { height: 43px; }
  .tabbar { height: calc(var(--tab-h) + var(--safe-bottom)); }
  .game-head { height: 58px; }
  .dig-panel { height: 144px; }
  .clean-panel { height: 202px; }
  .tool-btn { height: 52px; }
  .appraise-stage { height: 218px; }
  #appraiseImg { width: 178px; height: 178px; }
  .appraise-detail h2 { font-size: 22px; }
  .appraise-desc { display: none; }
  .offer-card { height: 52px; }
  .page-head { height: 64px; }
  .page-head h1 { font-size: 25px; }
  .museum-strip { height: 54px; }
  .lab-main { gap: 8px; }
}
@media (max-height: 680px) {
  .hero { height: 258px; min-height: 234px; }
  .hero-copy { bottom: 64px; }
  .hero-copy p { display: none; }
  .hero-copy h1 { font-size: 27px; }
  .hero-cta { height: 44px; bottom: 10px; }
  .season-line { display: none; }
  .home-main { padding-top: 4px; }
  .site-rail { height: 43px; }
  .stat-pair { height: 40px; }
  .dispatch-card { height: 39px; }
  .clean-panel { height: 190px; }
  .clean-hint { bottom: 12px; }
  .appraise-stage { height: 192px; }
  #appraiseImg { width: 158px; height: 158px; }
  .provenance-card { display: none; }
  .appraise-desc { display: none; }
  .appraise-stats { margin-top: 5px; }
  .offer-card { height: 49px; }
  .lab-window { min-height: 140px; }
  .empty-copy h2 { font-size: 22px; }
  .empty-copy p { margin-bottom: 8px; }
  .museum-hall { min-height: 175px; }
  .museum-strip { height: 48px; }
  .featured-img { width: 82px; height: 82px; }
}
@media (max-width: 350px) {
  .brand-title { font-size: 19px; }
  .topbar { padding-left: 12px; padding-right: 12px; }
  .home-main { padding-left: 11px; padding-right: 11px; }
  .hero-copy { left: 14px; right: 14px; }
  .hero-copy h1 { font-size: 28px; }
  .hero-arrow { display: none; }
  .site-chip .site-name { font-size: 10px; }
  .game-head { padding-left: 9px; padding-right: 9px; }
  .dig-stage, .clean-stage { margin-left: 8px; margin-right: 8px; }
  .game-panel { margin-left: 8px; margin-right: 8px; padding-left: 11px; padding-right: 11px; }
  .dig-panel .primary-btn, .clean-foot .primary-btn { width: 132px; }
  .field-note { display: none; }
  .appraise-main { padding-left: 12px; padding-right: 12px; }
  .museum-main, .shop-main, .lab-main { padding-left: 11px; padding-right: 11px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .001ms !important; animation-iteration-count: 1 !important; transition-duration: .001ms !important; }
}

