async (page) => {
  const sleep = ms => page.waitForTimeout(ms);
  const log = [];
  const snap = async (name) => page.screenshot({ path: `screenshots/${name}.png` });
  const sceneRect = async (stageSel, expr) => page.evaluate(({ stageSel, expr }) => {
    const scene = Function(`return (${expr})`)();
    const r = document.querySelector(stageSel).getBoundingClientRect();
    return { x: r.x, y: r.y, w: r.width, h: r.height, cx: scene.cx, cy: scene.cy, size: scene.size || scene.relicSize };
  }, { stageSel, expr });

  async function scribble(stageSel, expr, rows = 14, steps = 20, inset = .48) {
    const r = await sceneRect(stageSel, expr);
    const cx = r.x + r.cx, cy = r.y + r.cy;
    const rx = r.size * inset, ry = r.size * inset;
    await page.mouse.move(cx - rx, cy - ry);
    await page.mouse.down();
    for (let i = 0; i <= rows; i++) {
      const y = cy - ry + (2 * ry) * (i / rows);
      const x1 = cx - rx, x2 = cx + rx;
      if (i % 2 === 0) {
        await page.mouse.move(x1, y, { steps: Math.max(4, Math.round(steps / 3)) });
        await page.mouse.move(x2, y, { steps });
      } else {
        await page.mouse.move(x2, y, { steps: Math.max(4, Math.round(steps / 3)) });
        await page.mouse.move(x1, y, { steps });
      }
    }
    await page.mouse.up();
    await sleep(350);
  }

  await page.setViewportSize({ width: 390, height: 844 });
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  await sleep(600);
  const home = await page.evaluate(() => ({
    active: document.querySelector('.screen.is-active')?.id,
    scroll: [document.documentElement.scrollWidth, document.documentElement.scrollHeight],
    viewport: [innerWidth, innerHeight],
    coins: window.__DUNE.state.coins,
    cta: document.querySelector('#heroCtaText').textContent,
    tabbarBottom: document.querySelector('#screen-home .tabbar').getBoundingClientRect().bottom
  }));
  log.push({ step: 'fresh home', home });
  await snap('flow-01-home');

  await page.click('#beginDigBtn');
  await sleep(700);
  log.push({ step: 'dig opened', active: await page.evaluate(() => document.querySelector('.screen.is-active')?.id) });
  await snap('flow-02-dig');
  await scribble('#digStage', 'window.__DUNE.digScene');
  const digState = await page.evaluate(() => ({
    pct: window.__DUNE.digScene.progress,
    found: window.__DUNE.digScene.found,
    liftDisabled: document.querySelector('#liftBtn').disabled,
    note: document.querySelector('#digNote').textContent,
    exposure: document.querySelector('#exposureValue').textContent,
    signal: document.querySelector('#digSignal').textContent
  }));
  log.push({ step: 'dug', digState });
  await snap('flow-03-dig-exposed');

  await page.click('#liftBtn');
  await page.waitForFunction(() => window.__DUNE.cleanScene, null, { timeout: 5000 });
  await sleep(500);
  const cleanStart = await page.evaluate(() => {
    const c = window.__DUNE.cleanScene;
    return { active: document.querySelector('.screen.is-active')?.id, phase: c.phase, dirt: c.dirtCount / c.dirtTotal, salt: c.saltCount / c.saltTotal, tool: c.tool, relic: window.__DUNE.state.currentRelic };
  });
  log.push({ step: 'clean opened', cleanStart });
  await snap('flow-04-clean');

  await scribble('#cleanStage', 'window.__DUNE.cleanScene');
  const brushed = await page.evaluate(() => {
    const c = window.__DUNE.cleanScene;
    return { phase: c.phase, dirt: c.dirtCount / c.dirtTotal, salt: c.saltCount / c.saltTotal, grime: document.querySelector('#grimePct').textContent };
  });
  log.push({ step: 'brushed', brushed });
  await snap('flow-05-clean-brushed');

  await page.click('[data-tool=water]');
  await sleep(100);
  await scribble('#cleanStage', 'window.__DUNE.cleanScene');
  const watered = await page.evaluate(() => {
    const c = window.__DUNE.cleanScene;
    return { phase: c.phase, dirt: c.dirtCount / c.dirtTotal, salt: c.saltCount / c.saltTotal, saltLabel: document.querySelector('#saltLabel').textContent, label: document.querySelector('#cleanRelicLabel').textContent };
  });
  log.push({ step: 'watered', watered });
  await snap('flow-06-clean-polish');

  await page.click('[data-tool=cloth]');
  await sleep(100);
  await scribble('#cleanStage', 'window.__DUNE.cleanScene', 16, 24, .46);
  const polished = await page.evaluate(() => {
    const c = window.__DUNE.cleanScene;
    return { phase: c.phase, polish: c.polish, complete: c.completed, appraiseDisabled: document.querySelector('#appraiseBtn').disabled, condition: window.__DUNE.state.currentRelic?.condition, grade: document.querySelector('#cleanGrade').textContent, btn: document.querySelector('#appraiseBtn span').textContent };
  });
  log.push({ step: 'polished', polished });
  await snap('flow-07-clean-done');

  await page.click('#appraiseBtn');
  await sleep(500);
  const appraise = await page.evaluate(() => ({
    active: document.querySelector('.screen.is-active')?.id,
    name: document.querySelector('#appraiseName').textContent,
    condition: document.querySelector('#appraiseCondition').textContent,
    market: document.querySelector('#appraiseMarket').textContent,
    museum: document.querySelector('#museumValue').textContent,
    collector: document.querySelector('#collectorValue').textContent,
    renown: document.querySelector('#museumRenown').textContent,
    offers: window.__DUNE.state.currentRelic?.offers,
    scroll: [document.documentElement.scrollWidth, document.documentElement.scrollHeight]
  }));
  log.push({ step: 'appraise', appraise });
  await snap('flow-08-appraise');

  const beforeSale = await page.evaluate(() => ({ coins: window.__DUNE.state.coins, renown: window.__DUNE.state.renown, collection: window.__DUNE.state.collection.length }));
  await page.click('#museumOffer');
  await sleep(500);
  const sold = await page.evaluate(() => ({
    overlay: !document.querySelector('#soldOverlay').hidden,
    coins: window.__DUNE.state.coins,
    renown: window.__DUNE.state.renown,
    collection: window.__DUNE.state.collection.length,
    currentRelic: window.__DUNE.state.currentRelic,
    amount: document.querySelector('#soldAmount').textContent,
    renownText: document.querySelector('#soldRenown').textContent,
    saved: JSON.parse(localStorage.getItem('dune_and_dust_save_v3'))
  }));
  log.push({ step: 'sold', beforeSale, sold: { ...sold, saved: { coins: sold.saved.coins, renown: sold.saved.renown, collection: sold.saved.collection.length, currentRelic: sold.saved.currentRelic } } });
  await snap('flow-09-sold');

  await page.click('#soldContinue');
  await sleep(500);
  log.push({ step: 'returned home', active: await page.evaluate(() => document.querySelector('.screen.is-active')?.id), coins: await page.evaluate(() => window.__DUNE.state.coins) });

  await page.click('[data-nav=museum]');
  await sleep(400);
  const museum = await page.evaluate(() => ({
    active: document.querySelector('.screen.is-active')?.id,
    count: document.querySelector('#museumCount').textContent,
    strip: document.querySelector('#stripCount').textContent,
    grade: document.querySelector('#museumGrade').textContent,
    value: document.querySelector('#museumValue').textContent,
    display: document.querySelector('#museumDisplay').innerText.slice(0, 100)
  }));
  log.push({ step: 'museum', museum });
  await snap('flow-10-museum');

  await page.click('[data-nav=shop]');
  await sleep(400);
  const shopBefore = await page.evaluate(() => ({
    active: document.querySelector('.screen.is-active')?.id,
    cards: document.querySelectorAll('.upgrade-card').length,
    first: document.querySelector('.upgrade-card').innerText.replace(/\n/g, ' | '),
    coins: window.__DUNE.state.coins
  }));
  log.push({ step: 'shop', shopBefore });
  await snap('flow-11-shop');

  await page.click('[data-upgrade=trowel]');
  await sleep(400);
  const shopAfter = await page.evaluate(() => ({
    level: window.__DUNE.state.levels.trowel,
    coins: window.__DUNE.state.coins,
    toast: document.querySelector('.toast:last-child')?.textContent || '',
    first: document.querySelector('.upgrade-card').innerText.replace(/\n/g, ' | ')
  }));
  log.push({ step: 'upgraded', shopAfter });
  await snap('flow-12-shop-upgraded');

  await page.reload();
  await sleep(700);
  const persisted = await page.evaluate(() => ({
    active: document.querySelector('.screen.is-active')?.id,
    coins: window.__DUNE.state.coins,
    renown: window.__DUNE.state.renown,
    trowel: window.__DUNE.state.levels.trowel,
    collection: window.__DUNE.state.collection.length,
    currentRelic: window.__DUNE.state.currentRelic,
    firstSale: window.__DUNE.state.flags.firstSale,
    firstRelic: window.__DUNE.state.flags.firstRelic,
    recovered: document.querySelector('#statRecovered').textContent,
    renownText: document.querySelector('#statRenown').textContent
  }));
  log.push({ step: 'persisted', persisted });
  await snap('flow-13-home-persisted');

  return log;
}

