async (page) => {
  const out = [];
  const sleep = ms => page.waitForTimeout(ms);
  const measure = async (name, selectors) => {
    const m = await page.evaluate(({ selectors }) => {
      const active = document.querySelector('.screen.is-active');
      const vw = innerWidth, vh = innerHeight;
      const items = selectors.map(sel => {
        const el = document.querySelector(sel);
        if (!el) return { sel, missing: true };
        const r = el.getBoundingClientRect();
        return {
          sel,
          top: +r.top.toFixed(1), bottom: +r.bottom.toFixed(1), left: +r.left.toFixed(1), right: +r.right.toFixed(1),
          w: +r.width.toFixed(1), h: +r.height.toFixed(1),
          clipped: r.top < -1 || r.left < -1 || r.bottom > vh + 1 || r.right > vw + 1
        };
      });
      return {
        active: active?.id,
        viewport: [vw, vh],
        scroll: [document.documentElement.scrollWidth, document.documentElement.scrollHeight],
        bodyScroll: [document.body.scrollWidth, document.body.scrollHeight],
        items,
        clipped: items.filter(i => i.clipped)
      };
    }, { selectors });
    out.push({ name, ...m });
    await page.screenshot({ path: `screenshots/layout-${name}.png` });
    return m;
  };

  await page.evaluate(() => localStorage.clear());
  await page.reload();
  await sleep(500);
  await page.setViewportSize({ width: 360, height: 640 });
  await sleep(500);
  await measure('360-home', ['#screen-home .topbar', '#screen-home .hero', '#screen-home .site-rail', '#screen-home .home-lower', '#screen-home .dispatch-card', '#screen-home .tabbar']);

  await page.evaluate(() => {
    const s = window.__DUNE.state;
    s.selectedSite = 0;
    s.currentRelic = null;
    s.collection = [];
    s.coins = 620;
    s.renown = 12;
    s.levels = { trowel: 1, sieve: 1, sonar: 1, brush: 1, water: 1, cloth: 1 };
    s.flags = { firstRelic: false, firstSale: false, tutorialDig: false, tutorialClean: false };
    window.__DUNE.save();
    window.__DUNE.showScreen('home');
  });
  await sleep(300);
  await page.click('#beginDigBtn');
  await sleep(700);
  await measure('360-dig', ['#screen-dig .game-head', '#digStage', '.dig-panel', '#liftBtn', '#scanBtn']);

  await page.evaluate(() => {
    const s = window.__DUNE.state;
    s.currentRelic = { artifactId: 'lamp', siteId: 'sunken-caravan', condition: null, dirt: 1, salt: 1, polish: 0, bonus: 0, foundAt: Date.now() };
    window.__DUNE.save();
    window.__DUNE.startClean();
  });
  await page.waitForFunction(() => window.__DUNE.cleanScene, null, { timeout: 5000 });
  await sleep(400);
  await measure('360-clean', ['#screen-clean .game-head', '#cleanStage', '.clean-panel', '.clean-meters', '.tool-dock', '#appraiseBtn']);

  await page.evaluate(() => {
    const s = window.__DUNE.state;
    s.currentRelic.condition = 93;
    s.currentRelic.dirt = 0;
    s.currentRelic.salt = 0;
    s.currentRelic.polish = 1;
    s.currentRelic.cat = '102';
    s.currentRelic.offers = { museum: 310, collector: 402, renown: 15, market: 355 };
    window.__DUNE.save();
    window.__DUNE.showScreen('lab');
  });
  await sleep(250);
  await page.click('#labCta');
  await sleep(450);
  await measure('360-appraise', ['#screen-appraise .game-head', '.appraise-stage', '.appraise-detail', '.offer-block', '#museumOffer', '#collectorOffer']);

  await page.evaluate(() => window.__DUNE.showScreen('lab'));
  await sleep(300);
  await measure('360-lab', ['#screen-lab .page-head', '.lab-main', '.lab-window', '.empty-copy', '#labCta', '#screen-lab .tabbar']);

  await page.click('#screen-lab [data-nav=museum]');
  await sleep(350);
  await measure('360-museum', ['#screen-museum .page-head', '.museum-hall', '.museum-strip', '.museum-stats', '#screen-museum .tabbar']);

  await page.click('#screen-museum [data-nav=shop]');
  await sleep(350);
  await measure('360-shop', ['#screen-shop .page-head', '.segmented', '.upgrade-list', '.shop-note', '#screen-shop .tabbar']);

  await page.setViewportSize({ width: 320, height: 568 });
  await sleep(400);
  await page.evaluate(() => window.__DUNE.showScreen('home'));
  await sleep(300);
  await measure('320-home', ['#screen-home .hero', '#screen-home .site-rail', '#screen-home .dispatch-card', '#screen-home .tabbar']);

  await page.evaluate(() => {
    const s = window.__DUNE.state;
    s.currentRelic.condition = 93;
    s.currentRelic.offers = { museum: 310, collector: 402, renown: 15, market: 355 };
    window.__DUNE.showScreen('lab');
  });
  await sleep(250);
  await page.click('#labCta');
  await sleep(450);
  await measure('320-appraise', ['#screen-appraise .game-head', '.appraise-stage', '.appraise-detail', '.offer-block', '#museumOffer', '#collectorOffer']);

  return out;
}

