  --paper: #f3e8d3;
  --paper-2: #ead9ba;
  --paper-3: #dfcba7;
  --cream: #fff8ea;
  --gold: #d8a44d;
  --gold-deep: #a66b24;
  --gold-light: #f3cf84;
  --rust: #b45a32;
