async (page) => {
  const sleep = ms => page.waitForTimeout(ms);
  const log = [];
  const snap = name => page.screenshot({ path: `screenshots/final-${name}.png` });
  const sceneRect = (stageSel, expr) => page.evaluate(({ stageSel, expr }) => {
    const scene = Function(`return (${expr})`)();
    const r = document.querySelector(stageSel).getBoundingClientRect();
    return { x: r.x, y: r.y, w: r.width, h: r.height, cx: scene.cx, cy: scene.cy, size: scene.size || scene.relicSize };
  }, { stageSel, expr });
  async function scribble(stageSel, expr, rows = 14, steps = 22, inset = .48) {
    const r = await sceneRect(stageSel, expr);
    const cx = r.x + r.cx, cy = r.y + r.cy;
    const rx = r.size * inset, ry = r.size * inset;
    await page.mouse.move(cx - rx, cy - ry);
    await page.mouse.down();
    for (let i = 0; i <= rows; i++) {
      const y = cy - ry + (2 * ry) * (i / rows);
      const x1 = cx - rx, x2 = cx + rx;
      if (i % 2 === 0) {
        await page.mouse.move(x1, y, { steps: 8 });
        await page.mouse.move(x2, y, { steps });
      } else {
        await page.mouse.move(x2, y, { steps: 8 });
        await page.mouse.move(x1, y, { steps });
      }
    }
    await page.mouse.up();
    await sleep(300);
  }

  await page.setViewportSize({ width: 390, height: 844 });
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  await sleep(650);

  const home = await page.evaluate(() => ({
    active: document.querySelector('.screen.is-active')?.id,
    noScroll: document.documentElement.scrollHeight === innerHeight && document.documentElement.scrollWidth === innerWidth,
    cta: document.querySelector('#heroCtaText').textContent,
    coins: window.__DUNE.state.coins,
    duplicates: [...document.querySelectorAll('[id]')].map(e => e.id).filter((id, i, a) => a.indexOf(id) !== i),
    tabbar: (() => { const r = document.querySelector('#screen-home .tabbar').getBoundingClientRect(); return { top: r.top, bottom: r.bottom }; })()
  }));
  log.push({ home });
  await snap('01-home');

  await page.click('#beginDigBtn');
  await sleep(700);
  await scribble('#digStage', 'window.__DUNE.digScene');
  const dug = await page.evaluate(() => ({
    pct: Math.round(window.__DUNE.digScene.progress * 100),
    found: window.__DUNE.digScene.found,
    liftEnabled: !document.querySelector('#liftBtn').disabled
  }));
  log.push({ dug });
  await snap('02-dig');

  await page.click('#liftBtn');
  await page.waitForFunction(() => window.__DUNE.cleanScene, null, { timeout: 5000 });
  await sleep(450);
  await scribble('#cleanStage', 'window.__DUNE.cleanScene');
