373:         artifact,
374:         audio,
375:         onUpdate: ({ pct, stratum, depth, found, signal }) => {
376:           $('#exposureValue').textContent = `${pct}%`;
377:           $('#exposureBar').style.width = `${pct}%`;
378:           $('#digStratum').textContent = `Stratum ${stratum}`;
379:           $('#digDepth').textContent = `${depth} m`;
