565: function appraisalOffers() {
566:   const relic = state.currentRelic;
567:   if (!relic) return null;
568:   const artifact = artifactFor(relic.artifactId);
569:   const condition = relic.condition ?? 85;
570:   const market = Math.round(artifact.value * (.62 + (condition / 100) * .72));
571:   const collector = Math.round(market * (1.1 + Math.random() * .13));
572:   const museum = Math.round(market * .89);
573:   const renown = Math.round(artifact.rarity * 2.4 + condition / 15) + (state.flags.firstSale ? 0 : 3);
574:   return { artifact, condition, market, collector, museum, renown };
575: }
