579:   if (!relic) return;
580:   const offers = appraisalOffers();
581:   if (!offers) return;
582:   if (!relic.offers) {
583:     relic.offers = { collector: offers.collector, museum: offers.museum, renown: offers.renown, market: offers.market };
584:     save();
