593:   $('#appraisePulse').textContent = offers.condition >= 95
594:     ? 'Exceptional condition · collector interest high'
595:     : a.rarity >= 4
596:       ? 'Museum-tier rarity · demand rising'
597:       : 'Steady demand · comparable sales this season';
598:   $('#appraiseCondition').textContent = `${offers.condition}%`;
599:   $('#appraiseMarket').textContent = money(o.market);
600:   $('#appraiseGrade').textContent = gradeText(offers.condition);
601:   $('#appraiseStamp').textContent = offers.condition >= 95 ? 'Museum grade' : offers.condition >= 84 ? 'Conserved' : 'Stable';
602:   $('#appraiseId').textContent = `CAT. 0${relic.cat || 101}`;
603:   $('#appraiseRarity').innerHTML = Array.from({ length: 5 }, (_, i) =>
604:     `<svg class="star ${i < a.rarity ? '' : 'empty'}"><use href="#i-star"></use></svg>`
605:   ).join('') + `<span class="rarity-text">${['', 'Common', 'Notable', 'Rare', 'Museum', 'Masterwork'][a.rarity]}</span>`;
606:   $('#museumOfferValue').textContent = money(o.museum);
