612: function sellRelic(buyer) {
613:   const relic = state.currentRelic;
614:   if (!relic || !relic.offers) return;
615:   const artifact = artifactFor(relic.artifactId);
616:   const offers = relic.offers;
617:   const amount = buyer === 'museum' ? offers.museum : offers.collector;
618:   let grant = 0;
619:   let grantNote = '';
620:   if (!state.flags.firstRelic) {
621:     grant += 150;
622:     state.flags.firstRelic = true;
623:     grantNote = `The Society adds a first-find grant of ${money(150)}.`;
624:   }
625:   if (!state.flags.galleryBonus && state.collection.length + 1 >= 3) {
626:     grant += 200;
627:     state.flags.galleryBonus = true;
628:     grantNote = `${grantNote ? grantNote + ' ' : ''}A gallery milestone adds ${money(200)}.`;
629:   }
630:   state.coins += amount + grant;
631:   state.totalEarned += amount + grant;
632:   if (buyer === 'museum') state.renown += offers.renown;
633:   state.flags.firstSale = true;
634:   state.collection.push({
635:     artifactId: relic.artifactId,
636:     name: artifact.name,
637:     condition: relic.condition ?? 85,
638:     value: amount,
639:     buyer: buyer === 'museum' ? 'Atlas Museum' : 'Private collector',
640:     renown: buyer === 'museum' ? offers.renown : 0,
641:     date: Date.now()
642:   });
643:   state.currentRelic = null;
644:   save();
645:   updateWallet(true);
646:   updateBadges();
647: 
648:   const isMuseum = buyer === 'museum';
649:   $('#soldEyebrow').textContent = isMuseum ? 'Acquired by the Atlas Museum' : 'Sold to a private collector';
650:   $('#soldTitle').innerHTML = isMuseum ? 'A new treasure<br>enters the archive.' : 'The deal is<br>done, quietly.';
651:   $('#soldAmount').textContent = money(amount + grant);
652:   $('#soldRenown').textContent = isMuseum ? `+${offers.renown}` : '—';
653:   const buyerNote = isMuseum
654:     ? 'Curator Hana places it in the sunrise gallery.'
655:     : 'The buyer asks that you do not mention the tomb.';
656:   $('#soldFlavor').textContent = grantNote ? `${grantNote} ${buyerNote}` : buyerNote;
657:   $('#soldOverlay').hidden = false;
658:   audio.coin();
659:   vibrate([20, 40, 30]);
660: }
