    ctx.fill();
    ctx.strokeStyle = '#0b0a0b';
    ctx.lineWidth = 1.3;
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(-31, 56);
    ctx.quadraticCurveTo(0, 63, 31, 56);
    ctx.strokeStyle = 'rgba(205, 168, 88, .45)';
    ctx.lineWidth = 1.5;
    ctx.stroke();

    // reflections
    ctx.beginPath();
    ctx.moveTo(-30, -42);
    ctx.bezierCurveTo(-27, -22, -17, -13, -6, -10);
