  mirror(ctx) {
    ctx.save();
    ctx.translate(100, 101);

    // handle
    ctx.beginPath();
    ctx.moveTo(-10, 40);
    ctx.lineTo(-8, 72);
    ctx.quadraticCurveTo(0, 78, 8, 72);
