import { createRequire } from 'node:module';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
const errors = [];
page.on('pageerror', e => errors.push(`pageerror: ${e.message}`));
page.on('console', m => { if (m.type() === 'error') errors.push(`console: ${m.text()}`); });
await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.waitForTimeout(500);

const initial = await page.evaluate(() => ({
  title: document.title,
  fieldCount: document.querySelector('#fieldBookCount')?.textContent,
  stat: document.querySelector('#statRecovered')?.parentElement?.textContent?.trim(),
  bookHidden: document.querySelector('#collectionBook')?.hidden,
  sites: window.__DUNE?.state ? undefined : 'no dune'
}));

await page.screenshot({ path: '/tmp/opencode/home.png' });
await page.click('#openFieldCollectionBook');
await page.waitForTimeout(300);
const opened = await page.evaluate(() => ({
  hidden: document.querySelector('#collectionBook')?.hidden,
  count: document.querySelector('#collectionBookCount')?.textContent,
  sections: document.querySelectorAll('.book-site').length,
  cards: document.querySelectorAll('.book-card').length,
  found: document.querySelectorAll('.book-card.is-found').length,
  firstSiteCards: document.querySelectorAll('.book-site:first-of-type .book-card').length,
  listHeight: document.querySelector('#collectionBookList')?.scrollHeight,
  clientHeight: document.querySelector('#collectionBookList')?.clientHeight
}));
await page.screenshot({ path: '/tmp/opencode/book.png' });

// Scroll to the last site and screenshot the lower half of the book.
await page.evaluate(() => {
  const list = document.querySelector('#collectionBookList');
  if (list) list.scrollTop = list.scrollHeight;
});
await page.waitForTimeout(200);
await page.screenshot({ path: '/tmp/opencode/book-bottom.png' });

// Open a discovered record by seeding one find into the live state.
const detail = await page.evaluate(() => {
  const dune = window.__DUNE;
  if (!dune) return { skipped: true };
  dune.state.collection.push({ artifactId: 'astrolabe', condition: 88, value: 420, buyer: 'Atlas Society' });
  document.querySelector('#closeCollectionBook').click();
  document.querySelector('#openFieldCollectionBook').click();
  const card = document.querySelector('[data-artifact="astrolabe"]');
  card?.click();
  return {
    cardFound: !!card,
    modalHidden: document.querySelector('#modal')?.hidden,
    modalTitle: document.querySelector('#modalTitle')?.textContent,
    modalText: document.querySelector('#modalText')?.textContent?.slice(0, 120)
  };
});
await page.waitForTimeout(200);
await page.screenshot({ path: '/tmp/opencode/book-detail.png' });

// Count unique canvas data URLs for all silhouettes to confirm every card has distinct art.
const artStats = await page.evaluate(async () => {
  document.querySelector('#modalClose')?.click();
  const imgs = [...document.querySelectorAll('.book-card img')];
  const srcs = imgs.map(img => img.src);
  return { images: imgs.length, unique: new Set(srcs).size, empty: srcs.filter(s => !s || s.length < 100).length };
});

console.log(JSON.stringify({ initial, opened, detail, artStats, errors }, null, 2));
await browser.close();

