/* =========================================================
   PRIVATE AUCTION
   ========================================================= */
.auction-overlay {
  position: absolute;
  inset: 0;
  z-index: 75;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background:
    radial-gradient(ellipse at 50% 12%, #3b2a1a 0%, #1a120c 44%, #070504 100%);
  animation: fadeIn .35s ease both;
}
.auction-overlay[hidden] { display: none; }
.auction-room {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
}
.auction-head {
  flex: 0 0 58px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: calc(7px + var(--safe-top)) 14px 5px;
  position: relative;
  z-index: 10;
  border-bottom: 1px solid rgba(231, 202, 146, .12);
  background: rgba(9, 6, 4, .38);
}
.auction-head > div { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.auction-kicker {
  font-size: 5.8px;
  line-height: 1.3;
  letter-spacing: .17em;
  text-transform: uppercase;
  color: #a58a61;
  font-weight: 700;
}
.auction-head strong {
  font-family: var(--font-display);
  font-size: 18px;
  line-height: 1.05;
  color: #f3e2c0;
  font-weight: 600;
}
.auction-skip {
  flex: 0 0 auto;
  height: 30px;
  padding: 0 10px;
  border-radius: 8px;
  border: 1px solid rgba(231, 202, 146, .16);
  background: rgba(255, 255, 255, .035);
  color: #b9a17b;
  font-size: 7px;
  font-weight: 800;
  letter-spacing: .12em;
  text-transform: uppercase;
}
.auction-skip:active { transform: scale(.96); }

.auction-stage {
  flex: 1;
  min-height: 0;
  position: relative;
  overflow: hidden;
}
.auction-stage::before {
  content: '';
  position: absolute;
  left: 50%;
  bottom: -16%;
  width: 150%;
  height: 55%;
  transform: translateX(-50%);
  border-radius: 50%;
  background: radial-gradient(ellipse, rgba(190, 139, 75, .22), transparent 62%);
  filter: blur(8px);
}
.auction-stage::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(180deg, rgba(4, 3, 2, .34), transparent 20%, transparent 72%, rgba(4, 3, 2, .58)),
    radial-gradient(ellipse at 50% 45%, transparent 44%, rgba(4, 3, 2, .45) 100%);
  z-index: 7;
}
.auction-beam {
  position: absolute;
  left: 50%;
  top: -8%;
  width: 280px;
  height: 92%;
  transform: translateX(-50%);
  background: conic-gradient(from 171deg at 50% 0%, transparent 0deg, rgba(255, 226, 165, .14) 8deg, transparent 19deg);
  filter: blur(9px);
  opacity: .8;
  z-index: 1;
}
.auction-crowd {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.bidder {
  position: absolute;
  width: 56px;
  height: 108px;
  transform-origin: bottom center;
  animation: bidderSway 5.4s ease-in-out infinite;
  z-index: 4;
}
.bidder-head {
  position: absolute;
  top: 0;
  left: 50%;
  width: 24px;
  height: 27px;
  transform: translateX(-50%);
  border-radius: 50% 50% 44% 44%;
  background: radial-gradient(circle at 34% 27%, #8c7256 0%, #493729 46%, #1a130e 100%);
  box-shadow: inset -3px -3px 4px rgba(0, 0, 0, .25), 0 0 0 1px rgba(235, 205, 145, .04);
  z-index: 3;
}
.bidder-body {
  position: absolute;
  top: 24px;
  left: 50%;
  width: 47px;
  height: 79px;
  transform: translateX(-50%);
  border-radius: 22px 22px 9px 9px;
  background: linear-gradient(180deg, #342b24 0%, #191410 58%, #0c0907 100%);
  box-shadow: inset 0 0 0 1px rgba(235, 205, 145, .045), 0 12px 18px rgba(0, 0, 0, .28);
  z-index: 2;
}
.bidder-arm {
  position: absolute;
  top: 37px;
  left: 50%;
  width: 5px;
  height: 39px;
  border-radius: 3px;
  background: #19130f;
  transform-origin: top center;
  transform: rotate(13deg);
  transition: transform .32s cubic-bezier(.2, .8, .2, 1);
  z-index: 4;
}
.bidder-sign {
  position: absolute;
  top: -13px;
  left: 50%;
  min-width: 43px;
  padding: 4px 6px;
  border-radius: 4px;
  border: 1px solid rgba(94, 67, 29, .45);
  background: linear-gradient(180deg, #f7e4b1, #ddbe7e);
  color: #2b1c0a;
  font-family: var(--font-display);
  font-size: 12px;
  line-height: 1;
  font-weight: 700;
  white-space: nowrap;
  text-align: center;
  box-shadow: 0 7px 14px rgba(0, 0, 0, .38);
  opacity: 0;
  transform: translateX(-50%) translateY(12px) rotate(-4deg) scale(.86);
  transition: opacity .18s ease, transform .32s cubic-bezier(.2, .8, .2, 1);
  z-index: 6;
}
.bidder-sign::after {
  content: '';
  position: absolute;
  left: 50%;
  bottom: -6px;
  width: 2px;
  height: 7px;
  transform: translateX(-50%);
  background: #8c6b3a;
}
.bidder.is-bidding .bidder-arm { transform: rotate(-38deg) translateY(-3px); }
.bidder.is-bidding .bidder-sign {
  opacity: 1;
  transform: translateX(-50%) translateY(-5px) rotate(-4deg) scale(1);
}
.bidder.is-winner .bidder-sign {
  border-color: rgba(244, 208, 131, .9);
  box-shadow: 0 0 0 3px rgba(244, 208, 131, .16), 0 8px 18px rgba(0, 0, 0, .42);
}
.bidder-back-left { left: 17%; top: 19%; opacity: .82; animation-delay: -1.1s; }
.bidder-back-right { right: 17%; top: 19%; opacity: .82; animation-delay: -2.3s; }
.bidder-mid-left { left: 1%; top: 43%; animation-delay: -3.1s; }
.bidder-mid-right { right: 1%; top: 43%; animation-delay: -4.2s; }
.bidder-front-left { left: 6%; bottom: 4%; animation-delay: -.5s; }
.bidder-front-right { right: 6%; bottom: 4%; animation-delay: -2.8s; }
.bidder-mid-left .bidder-body { background: linear-gradient(180deg, #40342a, #1d1712 58%, #0c0907); }
.bidder-mid-right .bidder-body { background: linear-gradient(180deg, #2b2724, #171310 58%, #0a0807); }
.bidder-front-left .bidder-body { background: linear-gradient(180deg, #3b2e24, #1a140f 58%, #0b0806); }
.bidder-front-right .bidder-body { background: linear-gradient(180deg, #322923, #16120e 58%, #090706); }
.bidder-front-left .bidder-head,
.bidder-mid-left .bidder-head { background: radial-gradient(circle at 34% 27%, #9b7d5c 0%, #4b3828 46%, #1a130e 100%); }
.bidder-front-right .bidder-head,
.bidder-mid-right .bidder-head { background: radial-gradient(circle at 34% 27%, #755c47 0%, #3d2d21 46%, #16110c 100%); }

@keyframes bidderSway {
  0%, 100% { transform: translateY(0) rotate(-.6deg); }
  50% { transform: translateY(-3px) rotate(.6deg); }
}

.auction-bid-panel {
  position: absolute;
  top: 12px;
  left: 50%;
  z-index: 9;
  min-width: 144px;
  padding: 8px 15px 9px;
  transform: translateX(-50%);
  border-radius: 14px;
  border: 1px solid rgba(231, 202, 146, .23);
