import { createRequire } from 'node:module';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
const errors = [];
page.on('pageerror', e => errors.push(`pageerror: ${e.message}`));
page.on('console', m => { if (m.type() === 'error') errors.push(`console: ${m.text()}`); });

await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(400);

// --- Auction -------------------------------------------------------------
const beforeCoins = await page.evaluate(() => window.__DUNE.state.coins);
await page.evaluate(() => {
  window.__DUNE.state.currentRelic = {
    artifactId: 'astrolabe',
    siteId: 'sunken-caravan',
    condition: 92,
    cat: '107',
    offers: { museum: 520, collector: 640, renown: 8 }
  };
  window.__DUNE.sellRelic('collector');
});
await page.waitForTimeout(1500);
const mid = await page.evaluate(() => {
  const overlay = document.querySelector('#auctionOverlay');
  const signs = [...document.querySelectorAll('.bidder-sign')];
  return {
    overlayHidden: overlay.hidden,
    bid: document.querySelector('#auctionBid').textContent,
    count: document.querySelector('#auctionBidCount').textContent,
    status: document.querySelector('#auctionStatus').textContent,
    raisedArms: document.querySelectorAll('.bidder.is-bidding').length,
    visibleSigns: signs.filter(s => getComputedStyle(s).opacity !== '0').length,
    imgLoaded: document.querySelector('#auctionImg').naturalWidth > 0,
    name: document.querySelector('#auctionName').textContent,
    lot: document.querySelector('#auctionLot').textContent
  };
});
await page.screenshot({ path: '/tmp/opencode/auction-mid.png' });

await page.waitForSelector('#auctionContinue:not([hidden])', { timeout: 10000 });
await page.waitForTimeout(450);
const end = await page.evaluate(() => ({
  bid: document.querySelector('#auctionBid').textContent,
  count: document.querySelector('#auctionBidCount').textContent,
  status: document.querySelector('#auctionStatus').textContent,
  stampVisible: document.querySelector('#auctionSoldStamp').classList.contains('is-visible'),
  winners: document.querySelectorAll('.bidder.is-winner').length,
  raisedArms: document.querySelectorAll('.bidder.is-bidding').length,
  grant: document.querySelector('#auctionGrant').textContent,
  coins: window.__DUNE.state.coins,
  collection: window.__DUNE.state.collection.length,
  currentRelic: window.__DUNE.state.currentRelic
}));
await page.screenshot({ path: '/tmp/opencode/auction-end.png' });

await page.click('#auctionContinue');
await page.waitForTimeout(400);
const after = await page.evaluate(() => ({
  overlayHidden: document.querySelector('#auctionOverlay').hidden,
  homeVisible: !document.querySelector('#screen-home').hidden
}));

// --- Dig grime vs cleaning grime ----------------------------------------
const digInfo = await page.evaluate(async () => {
  const { SITES } = await import('/js/data.js');
  window.__DUNE.startDig(SITES[2]);
  await new Promise(r => setTimeout(r, 450));
  const d = window.__DUNE.digScene;
  const ctx = d.sand.ctx;
  ctx.save();
  ctx.globalCompositeOperation = 'destination-out';
  ctx.beginPath();
  ctx.arc(d.cx, d.cy, d.relicSize * .48, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
  d.progress = .78;
  d.found = true;
  d.emit();
  return { artifact: d.artifact.id, art: d.artifact.art, w: d.w, h: d.h };
});
await page.waitForTimeout(300);
await page.screenshot({ path: '/tmp/opencode/dig-dirty.png' });

const digSample = await page.evaluate(() => {
  const d = window.__DUNE.digScene;
  const c = d.relicCanvas.c;
  const ctx = c.getContext('2d');
  const data = ctx.getImageData(c.width / 2 - 40, c.height / 2 - 40, 80, 80).data;
  let r = 0, g = 0, b = 0, a = 0, n = 0;
  for (let i = 0; i < data.length; i += 4) {
    if (data[i + 3] > 8) { r += data[i]; g += data[i + 1]; b += data[i + 2]; a += data[i + 3]; n++; }
  }
  return n ? { r: r / n, g: g / n, b: b / n, a: a / n, n } : null;
});

await page.evaluate(() => window.__DUNE.digScene.onLift());
await page.waitForTimeout(650);
await page.screenshot({ path: '/tmp/opencode/clean-start.png' });
const cleanInfo = await page.evaluate(() => {
  const s = window.__DUNE.cleanScene;
  const c = s.dirt.c;
  const ctx = c.getContext('2d');
  const data = ctx.getImageData(c.width / 2 - 40, c.height / 2 - 40, 80, 80).data;
  let r = 0, g = 0, b = 0, a = 0, n = 0;
  for (let i = 0; i < data.length; i += 4) {
    if (data[i + 3] > 8) { r += data[i]; g += data[i + 1]; b += data[i + 2]; a += data[i + 3]; n++; }
  }
  return {
    artifact: s.artifact.id,
    art: s.artifact.art,
    dirtPct: document.querySelector('#grimePct').textContent,
    saltPct: document.querySelector('#saltPct').textContent,
    dirtSample: n ? { r: r / n, g: g / n, b: b / n, a: a / n, n } : null
  };
});

console.log(JSON.stringify({ beforeCoins, mid, end, after, digInfo, digSample, cleanInfo, errors }, null, 2));
await browser.close();

content.text:
The auction scene looks good. Some observations:
- The podium artifact appears floating above a small label plate; the podium base is small compared to artifact. User asked "shows the artifact like on a podium". It does look like it's on a small plinth but the base is narrow and the artifact floats. Could enhance podium base with a taller pedestal. The screenshot shows the artifact over a small plaque, more like hovering. Maybe improve podium base to look like a real pedestal (taller with column). User specifically requested podium. We should make it more podium-like. Current `podium-base` is 154px wide, 8px padding, below artifact. It's more of a label plaque. Add a pedestal column beneath the artifact or make base taller with a trapezoid. But the artifact currently overlaps the base with margin-top -9px; screenshot shows a gap? Actually image is 172px and base sits below with -9 margin, the artifact's transparent area means visual gap. Could add a pedestal: a column under the image, with top surface. Let's design:

```
<div class="podium-base">
  <span class="podium-top"></span>? 
```

Better restructure: auction-podium contains halo, img, then podium-base. We can style `.podium-base::before` as a top slab and add `.podium-column` element. But easier: add a pseudo-element column extending downward and the label on front. Something like:

```
.podium-base {
  width: 170px;
  margin-top: -16px;
  padding: 0;
  border-radius: 6px;
  background: none;
  border: 0;
  box-shadow: none;
  position: relative;
}
.podium-base::before { /* top slab */ content:''; position:absolute; left:0; right:0; top:0; height:12px; background: linear-gradient(...); border:1px solid; border-radius: 50%/...; }
```

Alternatively simpler: keep current label plate but add a pedestal block between artifact and label:

In HTML:
```
<div class="auction-podium">
  <div class="podium-halo"></div>
  <img ...>
  <div class="podium-plinth" aria-hidden="true"></div>
  <div class="podium-base">...
```
with plinth being a tapered column ~70px wide and 42px tall, and base label beneath. But space is limited: podium bottom 11%, foot 88px. The screenshot has plenty of empty dark space; artifact at ~58% height, label at 72%. A pedestal column from artifact bottom to label would help.

Yet user's main request is bidders, count, signs. Those are there. Could still refine podium. Let's view dig and clean screenshots.

