import { createRequire } from 'node:module';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
page.on('pageerror', e => console.log('ERR', e.message));
await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(300);

const info = await page.evaluate(async () => {
  const { SITES } = await import('/js/data.js');
  window.__DUNE.startDig(SITES[2]);
  await new Promise(r => setTimeout(r, 400));
  const d = window.__DUNE.digScene;
  const before = d.sand.ctx.getImageData(d.cx * d.dpr, d.cy * d.dpr, 1, 1).data;
  const ctx = d.sand.ctx;
  ctx.save();
  ctx.globalCompositeOperation = 'destination-out';
  ctx.beginPath();
  ctx.arc(d.cx, d.cy, 100, 0, Math.PI * 2);
  ctx.fillStyle = '#000';
  ctx.fill();
  ctx.restore();
  const after = d.sand.ctx.getImageData(d.cx * d.dpr, d.cy * d.dpr, 1, 1).data;
  return { before: [...before], after: [...after], cx: d.cx, cy: d.cy, dpr: d.dpr, sandW: d.sand.c.width };
});
await page.waitForTimeout(300);
const canvasPixel = await page.evaluate(() => {
  const d = window.__DUNE.digScene;
  const c = d.canvas;
  const data = c.getContext('2d').getImageData(c.width / 2, c.height / 2, 1, 1).data;
  return [...data];
});
await page.screenshot({ path: '/tmp/opencode/debug-dig.png' });
console.log(JSON.stringify({ info, canvasPixel }, null, 2));
await browser.close();

