import { createRequire } from 'node:module';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 });
page.on('pageerror', e => console.log('ERR', e.message));
await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(300);

const box = await page.evaluate(async () => {
  const { SITES } = await import('/js/data.js');
  window.__DUNE.startDig(SITES[2]);
  await new Promise(r => setTimeout(r, 400));
  const d = window.__DUNE.digScene;
  const ctx = d.sand.ctx;
  ctx.save();
  ctx.globalCompositeOperation = 'destination-out';
  ctx.beginPath();
  ctx.arc(d.cx, d.cy, d.relicSize * .58, 0, Math.PI * 2);
  ctx.fillStyle = '#000';
  ctx.fill();
  ctx.restore();
  d.progress = .8; d.found = true; d.emit();
  const rect = d.canvas.getBoundingClientRect();
  return { x: rect.x + d.cx - 150, y: rect.y + d.cy - 150, width: 300, height: 300, art: d.artifact.id };
});
await page.waitForTimeout(250);
await page.screenshot({ path: '/tmp/opencode/dig-crop.png', clip: box });

await page.evaluate(() => window.__DUNE.digScene.onLift());
await page.waitForTimeout(700);
const cbox = await page.evaluate(() => {
  const s = window.__DUNE.cleanScene;
  const rect = s.canvas.getBoundingClientRect();
  return { x: rect.x + s.cx - 150, y: rect.y + s.cy - 150, width: 300, height: 300, art: s.artifact.id };
});
await page.screenshot({ path: '/tmp/opencode/clean-crop.png', clip: cbox });
console.log(JSON.stringify({ dig: box, clean: cbox }));
await browser.close();

