  const { SITES } = await import('/js/data.js');
  window.__DUNE.startDig(SITES[2]);
});
await page.waitForTimeout(500);

// Real pointer scrubbing across the artifact area.
const box = await page.evaluate(() => {
  const d = window.__DUNE.digScene;
  const r = d.canvas.getBoundingClientRect();
  return { x: r.x, y: r.y, cx: r.x + d.cx, cy: r.y + d.cy, size: d.relicSize };
});
await page.mouse.move(box.cx, box.cy);
await page.mouse.down();
for (let i = 0; i < 26; i++) {
  const a = i / 26 * Math.PI * 2;
  const rad = box.size * .34 * (i % 2 ? .6 : 1);
  await page.mouse.move(box.cx + Math.cos(a) * rad, box.cy + Math.sin(a) * rad, { steps: 3 });
}
await page.mouse.up();
