import { createRequire } from 'node:module';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
const errors = [];
page.on('pageerror', e => errors.push(`pageerror: ${e.message}`));
page.on('console', m => { if (m.type() === 'error') errors.push(`console: ${m.text()}`); });
await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(400);

const boot = await page.evaluate(() => ({
  home: !document.querySelector('#screen-home').hidden,
  title: document.title,
  bookHidden: document.querySelector('#collectionBook').hidden
}));

// Collection book still opens from the field.
await page.click('#openFieldCollectionBook');
await page.waitForTimeout(250);
const book = await page.evaluate(() => ({
  hidden: document.querySelector('#collectionBook').hidden,
  cards: document.querySelectorAll('.book-card').length,
  count: document.querySelector('#collectionBookCount').textContent
}));
await page.click('#closeCollectionBook');

// Museum sale keeps its existing receipt overlay.
await page.evaluate(() => {
  window.__DUNE.state.currentRelic = {
    artifactId: 'dinar', siteId: 'sunken-caravan', condition: 95, cat: '101',
    offers: { museum: 500, collector: 420, renown: 10 }
  };
  window.__DUNE.sellRelic('museum');
});
await page.waitForTimeout(250);
const museum = await page.evaluate(() => ({
  soldVisible: !document.querySelector('#soldOverlay').hidden,
  auctionHidden: document.querySelector('#auctionOverlay').hidden,
  eyebrow: document.querySelector('#soldEyebrow').textContent
}));
await page.evaluate(() => { document.querySelector('#soldOverlay').hidden = true; });

// Collector sale opens the auction, then Skip completes it.
await page.evaluate(() => {
  window.__DUNE.state.currentRelic = {
    artifactId: 'obsidian-mirror', siteId: 'obsidian-tomb', condition: 97, cat: '140',
    offers: { museum: 1200, collector: 1580, renown: 18 }
  };
  window.__DUNE.sellRelic('collector');
});
await page.waitForTimeout(900);
const auctionOpen = await page.evaluate(() => ({
  visible: !document.querySelector('#auctionOverlay').hidden,
  bid: document.querySelector('#auctionBid').textContent,
  count: document.querySelector('#auctionBidCount').textContent,
  signs: [...document.querySelectorAll('.bidder-sign')].filter(s => getComputedStyle(s).opacity !== '0').length,
  raised: document.querySelectorAll('.bidder.is-bidding').length
}));
await page.click('#auctionSkip');
await page.waitForTimeout(300);
const auctionSkipped = await page.evaluate(() => ({
  continueVisible: !document.querySelector('#auctionContinue').hidden,
  stamp: document.querySelector('#auctionSoldStamp').classList.contains('is-visible'),
  status: document.querySelector('#auctionStatus').textContent,
  bid: document.querySelector('#auctionBid').textContent,
  count: document.querySelector('#auctionBidCount').textContent
}));
await page.click('#auctionContinue');
await page.waitForTimeout(350);
const auctionClosed = await page.evaluate(() => ({
  hidden: document.querySelector('#auctionOverlay').hidden,
  home: !document.querySelector('#screen-home').hidden,
  coins: window.__DUNE.state.coins,
  collection: window.__DUNE.state.collection.length
}));

console.log(JSON.stringify({ boot, book, museum, auctionOpen, auctionSkipped, auctionClosed, errors }, null, 2));
await browser.close();

